"use strict";

// The third route: the fatal ending here is never WRITTEN. The body runs
// off its end when the flag is falsy, so the call returns `undefined` --
// which is neither `null` nor a constructor.
//
//     function fallsThrough(flag) {
//       if (flag) return 1;
//       // implicit `return undefined`
//     }
//     class Mode extends fallsThrough(FLAG) {}
//
// This module exists to pin that the implicit ending is treated as a real
// PATH rather than as an absent one. A model that counted only the written
// `return 1` would see a single ending here and could not conclude
// anything; a model that counted it and IGNORED the fallthrough would be
// unsound in the other direction, concluding from one path what only holds
// for two. node raises
// `TypeError: Class extends value undefined is not a constructor or null`
// on the falsy path and `... value 1 ...` on the truthy one.
const danger = require("./danger");

function dangerousOp(input) {
  return danger.explode(input);
}

function safeOp(input) {
  return "safe:" + input;
}

function fallsThrough(flag) {
  if (flag) return 1;
}

if (process.env.FIXTURE_LIB_MODE === "fast") {
  module.exports = dangerousOp;
  class Mode extends fallsThrough(process.env.FIXTURE_LIB_FLAG) {}

  void Mode;
}

module.exports = safeOp;
